    uint32_t nBucketIdx = pQServerStrc->nClientHashMask & nClientToken;
    /* LPCRITICAL_SECTION lpCriticalSection for EnterCriticalSection */ EnterCriticalSection(pQServerStrc->pClientBucketLocks + nBucketIdx);
    D2QServerClientConnectionStrc* pFoundClient = pQServerStrc->pQServerClientList[nBucketIdx];
    uint32_t ipAddrBytes = 0;
    for (; pFoundClient; pFoundClient = pFoundClient->pNextByToken) {
      if (pFoundClient->nClientToken == nClientToken) {
        ipAddrBytes = pFoundClient->ipAddress.S_un.S_addr;
        break;
      }
    }

    /* LPCRITICAL_SECTION lpCriticalSection for LeaveCriticalSection */ LeaveCriticalSection(pQServerStrc->pClientBucketLocks + nBucketIdx);
    CloseRemoteConnection(pQServerStrc, nClientToken, pReason, nParam);
